def run(slug):
 u='https://'+slug+'.recruitee.com/api/offers';audit={'ats':'recruitee','board':slug,'endpoint':u}
 try:
  r=requests.get(u,timeout=12);audit['status']=r.status_code
  if r.status_code!=200:return audit,[]
  a=r.json().get('offers',[]);audit['complete_feed_jobs']=len(a);out=[]
  for j in a:
   title=j.get('title','');loc=str(j.get('locations',[]))+' '+str(j.get('location',''))+' '+str(j.get('country',''))
   if not feeds.ROLE.search(title) or feeds.EXCLUDE.search(title) or not feeds.GEO.search(loc):continue
   if re.search(r'\b(?:France|Paris|Lyon)\b',loc,re.I):continue
   if 'staff' in title.lower() and not re.search('senior.*staff',title,re.I):continue
   out.append({'company':j.get('company_name')or slug,'title':title,'role':title,'location':loc,'url':j.get('careers_url'),'application_url':j.get('careers_apply_url'),'posting':feeds.plain(j.get('description',''))+'\n'+feeds.plain(j.get('requirements','')),'ats':'recruitee','published':j.get('published_at'),'full_feed_fields':j})
  audit['candidates']=len(out);return audit,out
 except Exception as e:audit['error']=str(e);return audit,[]
with concurrent.futures.ThreadPoolExecutor(max_workers=16)as pool:r=list(pool.map(run,dict.fromkeys(SLUGS)))
p=ROOT/'job-search/europe-recruitee-1585-2026-10-15-queue.json';rows=[x for _,a in r for x in a];p.write_text(json.dumps({'scope':'Complete public Recruitee employer feeds. Full scope and location review still required.','coverage':[x for x,_ in r],'candidates':rows},indent=2)+'\n');print(json.dumps({'feeds':len(r),'successful':sum(x.get('status')==200 for x,_ in r),'jobs':sum(x.get('complete_feed_jobs',0)for x,_ in r),'candidates':len(rows),'output':str(p)}))
